#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geom2D. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Record quadrilateral := Quad { qa : 'rV[R]_2; qb : 'rV[R]_2; qc : 'rV[R]_2; qd : 'rV[R]_2 }. Definition similar_quadrilaterals (Q1 Q2 : quadrilateral) : Prop := exists (k : R) (O : 'rV[R]_2) (theta : R), k > 0 /\ forall i : 'I_4, let v1 := [:: Q1.(qa); Q1.(qb); Q1.(qc); Q1.(qd)]`_i - O in let v2 := [:: Q2.(qa); Q2.(qb); Q2.(qc); Q2.(qd)]`_i - O in v2 = k *: (rotmx theta *m v1). Lemma similar_sym Q1 Q2 : similar_quadrilaterals Q1 Q2 -> similar_quadrilaterals Q2 Q1. Proof. move=> [k [O [theta [k_gt0 Hf]]]]. exists (1 / k)%R, O, (- theta)%R; split; first by apply Rinv_0_lt_0_compat. move=> i; rewrite Hf; field. Qed.
